import React from 'react';
import { FaMapMarkerAlt, FaCalendar, FaClock, FaUsers, FaVolleyballBall, FaEdit, FaTrash, FaRubleSign } from 'react-icons/fa';
import Button from '../common/Button/Button';
import styles from './AdvertCard.module.css';

const AdvertCard = ({ advert, isCreator, isParticipating, onSubscribe, onEdit, onDelete, onClick }) => {
    const levelColors = {
        'D1': '#10B981',
        'D2': '#3B82F6',
        'D3': '#F59E0B',
        'D4': '#EF4444',
        'D4Plus': '#8B5CF6'
    };

    const formatDate = (dateStr) => {
        const date = new Date(dateStr);
        return date.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
    };

    const participantsCount = advert.participantsCount || 0;
    const progressPercent = (participantsCount / advert.peopleCount) * 100;

    return (
        <div className={styles.card} onClick={onClick}>
            <div className={styles.cardHeader}>
                <div className={styles.levelBadge} style={{ background: levelColors[advert.gameLevel] || '#667eea' }}>
                    <FaVolleyballBall className={styles.levelIcon} />
                    <span>Уровень {advert.gameLevel === 'D4Plus' ? 'D4+' : advert.gameLevel}</span>
                </div>
                {isCreator && <div className={styles.creatorBadge}>Ваше объявление</div>}
                {isParticipating && !isCreator && <div className={styles.participatingBadge}>Вы участвуете</div>}
            </div>

            <div className={styles.cardContent}>
                <div className={styles.addressBlock}>
                    <FaMapMarkerAlt className={styles.addressIcon} />
                    <div>
                        <div className={styles.addressLabel}>Место проведения</div>
                        <div className={styles.addressValue}>{advert.address}</div>
                    </div>
                </div>

                <div className={styles.infoGrid}>
                    <div className={styles.infoItem}>
                        <FaCalendar className={styles.infoIcon} />
                        <div>
                            <div className={styles.infoLabel}>Дата</div>
                            <div className={styles.infoValue}>{formatDate(advert.date)}</div>
                        </div>
                    </div>
                    <div className={styles.infoItem}>
                        <FaClock className={styles.infoIcon} />
                        <div>
                            <div className={styles.infoLabel}>Время</div>
                            <div className={styles.infoValue}>{advert.startTime?.slice(0,5)} - {advert.endTime?.slice(0,5)}</div>
                        </div>
                    </div>
                </div>

                <div className={styles.participantsBlock}>
                    <div className={styles.participantsInfo}>
                        <div className={styles.participantsLabel}>Участники</div>
                        <div className={styles.participantsValue}>
                            <span className={styles.currentCount}>{participantsCount}</span>
                            <span className={styles.separator}>/</span>
                            <span className={styles.totalCount}>{advert.peopleCount}</span>
                            <span className={styles.unit}>человек</span>
                        </div>
                    </div>
                    <div className={styles.progressBar}>
                        <div className={styles.progressFill} style={{ width: `${progressPercent}%` }}></div>
                    </div>
                </div>

                <div className={styles.priceBlock}>
                    <FaRubleSign className={styles.priceIcon} />
                    <div>
                        <div className={styles.priceLabel}>Стоимость участия</div>
                        <div className={styles.priceValue}>{advert.cost} BYN</div>
                    </div>
                </div>
            </div>

            <div className={styles.cardFooter} onClick={(e) => e.stopPropagation()}>
                {isCreator ? (
                    <div className={styles.creatorActions}>
                        <Button size="small" variant="outline" onClick={onEdit}>Редактировать</Button>
                        <Button size="small" variant="danger" onClick={onDelete}>Удалить</Button>
                    </div>
                ) : (
                    <Button size="medium" fullWidth variant={isParticipating ? 'secondary' : 'primary'} onClick={onSubscribe}>
                        {isParticipating ? 'Отменить запись' : 'Записаться на игру'}
                    </Button>
                )}
            </div>
        </div>
    );
};

export default AdvertCard;
